function tableConstraintDefinitions(): Record<string,string> {
  const definitions:Record<string,string>={};
  for(const sql of Object.values(FISCAL_003_TABLE_BLUEPRINT_SQL)){
    for(const line of sql.split("\n")){
      const match=line.trim().match(/^CONSTRAINT\s+([a-z][a-z0-9_]*)\s+(.+?)(?:,)?$/);
      if(match) definitions[match[1]!] = `CONSTRAINT ${match[1]} ${match[2]!.replace(/,$/,"")}`;
    }
  }
  for(const statement of FISCAL_003_EXTRA_CONSTRAINT_SQL){
    const match=statement.match(/ADD CONSTRAINT\s+([a-z][a-z0-9_]*)\s+/);
    if(!match) throw new Error(`unnamed 003 constraint blueprint: ${statement}`);
    definitions[match[1]!] = statement;
  }
  return definitions;
}

function namedStatements(statements:readonly string[],pattern:RegExp):Record<string,string>{
  const definitions:Record<string,string>={};
  for(const statement of statements){
    const match=statement.match(pattern);
    if(!match) throw new Error(`unnamed 003 blueprint: ${statement}`);
    definitions[match[1]!] = statement;
  }
  return definitions;
}

